import { useRef, type CSSProperties, type KeyboardEvent } from "react";
import "./AccentPicker.css";

export type Accent = "myelin" | "emerald" | "amber" | "rose";

interface AccentOption {
  id: Accent;
  label: string;
}

const ACCENTS: readonly AccentOption[] = [
  { id: "myelin", label: "Myelin blue" },
  { id: "emerald", label: "Emerald" },
  { id: "amber", label: "Amber" },
  { id: "rose", label: "Rose" },
];

export interface AccentPickerProps {
  value: Accent;
  onChange: (accent: Accent) => void;
}

export function AccentPicker({ value, onChange }: AccentPickerProps) {
  const optionRefs = useRef<Array<HTMLButtonElement | null>>([]);

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const last = ACCENTS.length - 1;
    let target: number;

    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        target = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        target = index === 0 ? last : index - 1;
        break;
      case "Home":
        target = 0;
        break;
      case "End":
        target = last;
        break;
      default:
        return;
    }

    event.preventDefault();

    const option = ACCENTS[target];
    if (!option) {
      return;
    }

    optionRefs.current[target]?.focus();
    onChange(option.id);
  }

  return (
    <div role="radiogroup" aria-label="Accent colour" className="accent-picker">
      {ACCENTS.map((option, index) => {
        const selected = option.id === value;
        const swatchStyle = {
          "--swatch": `var(--accent-${option.id})`,
        } as CSSProperties;

        return (
          <button
            key={option.id}
            ref={(element) => {
              optionRefs.current[index] = element;
            }}
            type="button"
            role="radio"
            aria-checked={selected}
            tabIndex={selected ? 0 : -1}
            className="accent-option"
            onClick={() => onChange(option.id)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="accent-swatch" style={swatchStyle} aria-hidden="true" />
            <span className="accent-name">{option.label}</span>
            {selected && (
              <svg
                className="accent-check"
                viewBox="0 0 16 16"
                aria-hidden="true"
                focusable="false"
              >
                <path
                  d="M3 8.5 6.5 12 13 4.5"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            )}
          </button>
        );
      })}
    </div>
  );
}
